\label{def:presieve}
   Denote by $\omega$ and $\Omega$ the following normalised lower bound and upper bound sieves. Define them to handle the primes $2$ and $3$ directly and sift for the primes $5\leq p < P_1=N^{\delta_1^4}$ with a beta sieve with $\beta=200$ and level $D_1=N^{\delta_1^3/100}$. That is, 
   \begin{align*}
       \omega(n)\coloneqq \mathbf{1}_{(n,6)=1}\prod_{p < P_1}\left(1-\frac{1}{p}\right)^{-1}\sum_{d\mid n}\lambda^{-}(d),\quad \Omega(n)\coloneqq \mathbf{1}_{(n,6)=1}\prod_{p < P_1}\left(1-\frac{1}{p}\right)^{-1}\sum_{d\mid n}\lambda^{+}(d),
   \end{align*}
   where $\lambda^{\pm}(d)=\mu(d)\mathbf{1}_{d\mid \prod_{5\leq p < P_1}p}\mathbf{1}_{d\in \mathcal{D}^{\pm}}$ and $\mathcal{D}^-, \mathcal{D}^{+}$ are given by~\cite[equation (6.55)]{cribro} with $\beta=200$.

 \label{def:mainsieve} Let $D_{\mathrm{M},1}=N^{1/3-\delta_1}, D_{\mathrm{M},2}=N^{1/6-\delta_1}, P_1=N^{\delta_1^4}$.
    We say $f_\textup{M}$ is a \emph{main-sieve}, if for some $|C_{f_\textup{M}}|\ll \log N$ we have
    \begin{align*}
       f_\textup{M}(n)=C_{f_\textup{M}}\sum_{d\mid n}\lambda(d),
 \end{align*}
where the function $\lambda$ fulfils the following.
\begin{enumerate}
	\item $\lambda(1)=1$ and $\lambda(d)\neq 0$ implies $p\nmid d$ for all $p < P_1$.
	\item  $\lambda=\lambda_{1}\star\lambda_{2}$ with $|\lambda_{i}(d)|\ll \tau(d)^{O(1)}$, and  $\lambda_{1}$ is supported on $[1,D_{\mathrm{M},1}]$, and $\lambda_{2}$ is a sum of $O_{\delta_1}(1)$ many well-factorable functions supported on $[1,D_{\mathrm{M},2}]$. 
\end{enumerate}

\label{def_approx}
    Let $\epsilon>0$ and $f, g$ be finitely supported arithmetic functions. Let $\Omega$ denote the upper bound pre-sieve from Definition~\ref{def:presieve}. We write $f\approx_{\epsilon} g$ if for every $|h(n)|\leq \Omega(n)\Omega(n+2)$ it holds that
    \begin{align*}
		\bigl|\sum_{\substack{n_1+n_2=m\\ N/2< n_1,n_2\leq N}}(f-g)(n_1) h(n_2)\bigr| \leq  \epsilon  m \bigl(\mathfrak{S}(m)+1\bigr)
	\end{align*}
    for all $m\in [5N/4,7N/4]$ with at most $N^{1-(\delta_1/10)^{4}}$ exceptions.

