\label{le_chensieve}
Assume that $N$ is sufficiently large, and let $P_1=N^{\delta_1^4}$. There exist main-sieves 
\begin{align*}
    \omega_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^\omega_{\textup{M}}(d),\\
    \Omega_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^\Omega_{\textup{M}}(d),\\
    \Omega'_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^{\Omega'}_{\textup{M}}(d),
\end{align*}
as in Definition~\ref{def:mainsieve}, and an error function $E(n)$ such that the following three statements hold. 
\begin{enumerate}[label=(\roman*)]
\item Let $\omega,\Omega$ be pre-sieves as in Definition~\ref{def:presieve} and denote
\begin{align*}
    g_1(n)&=\Lambda(n)\Omega(n+2)\omega_{\textnormal{M}}(n+2), \\
    g_2(n)&=(3/5+\delta_1)c_{E_3^*}\Omega(n)\Omega_{\textnormal{M}}(n)\Lambda_{E_3^*}(n+2), \\
    g_3(n)&=\Lambda(n)\bigl(\omega -\Omega\bigr)(n+2)\Omega'_{\textnormal{M}}(n+2).
\end{align*}
We have for $N/2< n\leq N$ the inequality
\begin{align}\label{eq:chenlower_minorisation}
    \Lambda(n)\Lambda_2(n+2)\geq g_1(n)-g_2(n)+g_3(n)+\Lambda(n)E(n+2).
\end{align}
    \item The sieve weights fulfil
    \begin{align}\label{eq:chentrivial_numerics}
     \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \left(\sum_{d}\frac{\lambda^{\Omega'}_{\textup{M}}(d)}{\varphi(d)}\right)\ll 1,
    \end{align}
    and, if $\delta_1$ is sufficiently small, there exists an absolute constant $c_0>0$ such that
\begin{align}\label{eq:chenlower_numerics}
   \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \left(\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}-(3/5+\delta_1) c_{E_3^*}\sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}\right)\geq c_0.
\end{align}

\item We have the approximation
\begin{align} \label{eq:chenlower_error}
    \Lambda(n)E(n+2)\approx_{N^{-1/100}} 0
\end{align}
in the sense of Definition~\ref{def_approx}.

\end{enumerate}

    The proof is an incorporation of pre-sieves into the construction of~\cite[Appendix A]{matomaki-shao}. In the case of lower bound sieves, Lemma~\ref{lem_lowerboundsievcomp} is used to facilitate this. 

