    \begin{align}\label{eq:chenlower1}
        \Lambda_2(n)\geq r_{N^{1/10}}(n)\left( 1-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}1-\frac{1}{2}\mathbf{1}_{n\in B_1}-\mathbf{1}_{n\in B_2}-E'(n)\right),
    \end{align}
    where 
    \begin{align*}
        0\leq E'(n)\ll \sum_{\substack{p^2\mid n \\ p \geq N^{1/10}}}1
    \end{align*}
