    \begin{align*}
        A&=r_{P_1}(n),\\
        B&=r_{[P_1,N^{1/10})}(n)-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}r_{[P_1,N^{1/10})}(n)
    \end{align*}
    with $\omega, \Omega$ as in Definition~\ref{def:presieve}. We choose
    \begin{align*}
        A^-&=\omega(n),\\
        A^+&=\Omega(n),
    \end{align*}
    so that 
    \begin{align*}
        A^-\leq A \leq A^+.
    \end{align*}
    We lower bound $B$ as in~\cite[Appendix A.3]{matomaki-shao}, using the well-factorable sieve from Lemma~\ref{lem:wellfac} with $\varepsilon=\delta_1^3$. We apply a lower bound linear sieve of range $[P_1,N^{1/10})$ and level $N^{1/2-2\delta_1}$ to the first component. Separately for each $p$, we use an upper bound linear sieve with range $[P_1,N^{1/10})$ and level $N^{1/2-2\delta_1}/p$ on $r_{[P_1,N^{1/10})}$. The sum of both sieves (including summation over $p$) is admissible for Definition~\ref{def:mainsieve}, and so we get the existence of some main-sieve $\omega_{\textup{M}}$ such that for
    \begin{align*}
        B^-=\omega_{\textup{M}}(n),
    \end{align*}
 we have
    \begin{align*}
        B^-\leq B.
    \end{align*}
    Clearly
    \begin{align*}
        B\leq r_{[P_1,N^{1/10})}(n)\leq \Omega'_{\textnormal{M}}(n)\coloneqq B^+,
    \end{align*}
    where $\Omega'_{\textnormal{M}}$ is the (well-factorable) upper bound linear sieve with range $[P_1,N^{1/10})$ and level $N^{1/2-2\delta_1}$. By the basic theory of the beta-sieve~\cite[Theorem 11.12]{cribro} and Mertens' theorem, the left-hand side of~\eqref{eq:chentrivial_numerics} is bounded in absolute terms. 
    Since $A=r_{P_1}(n)\geq0$ and $B^+=\Omega'_{\textnormal{M}}(n)\geq r_{[P_1,N^{1/10})}(n)\geq0$, the hypotheses of Lemma~\ref{lem_lowerboundsievcomp} hold, and it gives
    \begin{align}\label{eq:3.9firstlower}
     r_{N^{1/10}}(n)\left(1-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}1\right)\geq \Omega(n)\omega_{\textnormal{M}}(n)+(\omega-\Omega)(n)\Omega'_{\textnormal{M}}(n).
    \end{align}
    Plugging this into~\eqref{eq:chenlower1b}, we get for $N/2< n \leq N-2$ that 
    \begin{align}\begin{split}\label{eq:chensieveLupper}
    &\Lambda(n)\Lambda_2(n+2)\\
    \geq& g_1(n)+g_3(n)-\Lambda(n)c_{E_3^*} (n+2)\Lambda_{E_3^*}(n+2)+\Lambda(n)E(n+2).
    \end{split}
    \end{align}
    We follow~\cite[Appendix A.4]{matomaki-shao} to majorise
    \begin{align*}
        \Lambda(n)\leq (\log N)\prod_{p<N^{1/6}}\left(1-\frac{1}{p}\right)\cdot r_{P_1}(n) r_{[P_1,N^{1/6})}(n)\leq (\log N)\prod_{p<N^{1/6}}\left(1-\frac{1}{p}\right)\cdot  \Omega (n)\Omega_{\textnormal{M}}(n),
    \end{align*}
    where $\Omega_{\textnormal{M}}$ is the (well-factorable) upper bound linear sieve with range $[P_1,N^{1/6})$ and level $N^{1/2-2 \delta_1}$.
    Observe further that by~\eqref{eq:c_E}, we have $c_{E_3^*}(n+2)=c_{E_3^*}(N)(1+O((\log N)^{-1}))$ and recall that we write $c_{E_3^*}(N) \log N=c_{E_3^*} $. By Mertens' theorem,
    \begin{align*}
        \prod_{p<N^{1/6}}\Bigl(1-\frac1p\Bigr)=\prod_{N^{1/10}\leq p<N^{1/6}}\Bigl(1-\frac1p\Bigr)\prod_{p<N^{1/10}}\Bigl(1-\frac1p\Bigr)=\Bigl(\frac35+O(\delta_1)\Bigr)\prod_{p<N^{1/10}}\Bigl(1-\frac1p\Bigr),
    \end{align*}
    the middle factor tending to $(1/10)/(1/6)=3/5$. The remaining product $\prod_{p<N^{1/10}}(1-1/p)$ cancels against the normalisations built into $\Omega(n)$ and $\Omega_{\textnormal{M}}(n)$, leaving exactly the factor $3/5+O(\delta_1)$ recorded in $g_2$. We apply Mertens' theorem and this approximation so that for any $\delta_1>0$ and $N$ sufficiently large in terms of $\delta_1$, we have
    \begin{align*}
        \Lambda(n)c_{E_3^*} (n+2)\Lambda_{E_3^*}(n+2)\leq&(3/5+\delta_1)c_{E_3^*}\Omega(n)\Omega_{\textnormal{M}}(n)\Lambda_{E_3^*}(n+2) \\
        =&g_2(n).
    \end{align*}
    Together with~\eqref{eq:chensieveLupper} and since the contribution of $n\in \{N-1,N\}$ can be absorbed in the error term, this shows~\eqref{eq:chenlower_minorisation}.

    The proof of~\eqref{eq:chenlower_numerics} follows from the calculations in~\cite[Appendices A.3, A.4, A.5]{matomaki-shao}. Indeed by Lemma~\ref{lem:wellfac}, we have
    \begin{align*}
        \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1}\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}&\geq f(5)-\frac{1}{2}\sum_{N^{1/10}\leq p <N^{1/3-\delta_1}}\frac{F(5-10 \log p/\log N)}{\varphi(p)} -O(\delta_1)\\
        &\geq f(5)-\frac{1}{2}\int_{1/10}^{1/3} F(5-10 t) \frac{\,\mathrm{d} t}{t}-O(\delta_1)
    \end{align*}
    and
    \begin{align*}
             \frac{3}{5}c_{E_3^*}\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1}\sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}\leq \frac{1}{2}\cdot \frac{3}{5}F(3) \int_{\substack{1/10\leq t_1\leq 1/3\leq t_2\leq (1-t_1)/2\\ 1-t_1-t_2\geq 1/10}}\frac{\,\mathrm{d} t_1 \,\mathrm{d} t_2}{t_1t_2(1-t_1-t_2)}+O(\delta_1).
        \end{align*}
        That the difference of these is strictly positive for sufficiently small $\delta_1$ is stated explicitly in \cite[Appendix A.5]{matomaki-shao}.

\begin{align}\label{eq:chenlower1}
        \Lambda_2(n)\geq r_{N^{1/10}}(n)\left( 1-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}1-\frac{1}{2}\mathbf{1}_{n\in B_1}-\mathbf{1}_{n\in B_2}-E'(n)\right),
    \end{align}

\begin{align*}
         r_{N^{1/10}}(n)\left(1-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}1\right)&=r_{P_1}(n)\left(r_{[P_1,N^{1/10})}(n)-\frac{1}{2}\sum_{\substack{p\mid n \\ N^{1/10}\leq p \leq N^{1/3-\delta_1}}}r_{[P_1,N^{1/10})}(n) \right),
    \end{align*}

\begin{align*}
        \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1}\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}&\geq f(5)-\frac{1}{2}\sum_{N^{1/10}\leq p <N^{1/3-\delta_1}}\frac{F(5-10 \log p/\log N)}{\varphi(p)} -O(\delta_1)\\
        &\geq f(5)-\frac{1}{2}\int_{1/10}^{1/3} F(5-10 t) \frac{\,\mathrm{d} t}{t}-O(\delta_1)
    \end{align*}

\label{lem:P_1P_0majo}
    Recall the parameter choices in Definition~\ref{def:para}: $P_1=N^{\delta_1^4}$, $P_0=N^{\delta_1}$, $D_{\mathrm{M},1}=N^{1/3-\delta_1}$. There exist main-sieves
    \begin{align*}
        \omega_{[P_1,P_0)}(n)&=\sum_{d\mid n}\lambda^\omega_{\textup{M}}(d),\\
        \Omega_{[P_1,P_0)}(n)&=\sum_{d\mid n}\lambda^\Omega_{\textup{M}}(d)
    \end{align*}
    such that
    \begin{align}\label{eq:lemaP_1P_01}
         \omega_{[P_1,P_0)}(n)\leq r_{[P_1,P_0)}(n) \leq  \Omega_{[P_1,P_0)}(n)
    \end{align}
    and
    \begin{align}
    \label{eq:P1P0majo1} 
    \begin{aligned}
    \prod_{P_1\leq p < P_0}\Bigl(1-\frac{1}{p}\Bigr)^{-1}\sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}&=1+O\bigl(e^{-\frac{\log D_{\mathrm{M},1}}{40 \log P_0}}+\delta_1^{15}\bigr),\\
        \prod_{P_1\leq p < P_0}\Bigl(1-\frac{1}{p}\Bigr)^{-1}\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}&=1+O\bigl(e^{-\frac{\log D_{\mathrm{M},1}}{40 \log P_0}}+\delta_1^{15}\bigr).
       \end{aligned}
    \end{align}

\begin{align}
    \label{eq:P1P0majo1} 
    \begin{aligned}
    \prod_{P_1\leq p < P_0}\Bigl(1-\frac{1}{p}\Bigr)^{-1}\sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}&=1+O\bigl(e^{-\frac{\log D_{\mathrm{M},1}}{40 \log P_0}}+\delta_1^{15}\bigr),\\
        \prod_{P_1\leq p < P_0}\Bigl(1-\frac{1}{p}\Bigr)^{-1}\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}&=1+O\bigl(e^{-\frac{\log D_{\mathrm{M},1}}{40 \log P_0}}+\delta_1^{15}\bigr).
       \end{aligned}
    \end{align}

We let $\Omega_{[P_1,P_0)}(n)$ be the sum of the $O_{\delta_1}(1)$ well-factorable upper-bound linear sieve weights of Lemma~\ref{lem:wellfac} with sifting range $[P_1,P_0)$ and level $D_{\mathrm{M},1}=N^{1/3-\delta_1}$, normalised by $\prod_{P_1\leq p < P_0}\bigl(1-1/p\bigr)^{-1}$; see Lemma~\ref{lem:wellfac}. By construction, this fulfils~\eqref{eq:lemaP_1P_01}. Since the sifting range includes no primes less than $P_1$ and the level is $D_{\mathrm{M},1}$, this fits Definition~\ref{def:mainsieve}. The condition~\eqref{eq:P1P0majo1} follows from the basic theory of the linear sieve; see for example~\cite[Theorem 11.12, eq. (11.134)]{cribro}. Note that strictly speaking only one-sided inequalities are proved there; the asymptotics follow from the fact that 
\begin{align*}
   \sum_{d} \frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}\leq \sum_d \frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}.
\end{align*}

\label{def:Fouriernorm}
    For a function $f:\mathbb{N}\to \mathbb{C}$, define its \emph{Fourier norm} as
    \begin{align*}
        \|f\|_{\infty}^{\wedge}\coloneqq \sup_{\alpha \in \mathbb{R}}\left|\sum_{N/2< n\leq N}f(n)e(\alpha n)\right|.    
    \end{align*}

\label{lem_fourierimpliesapprox}
    Let $f_1,f_2:{\mathbb N}\to \mathbb{C}$. If
	\begin{align*}
		\|f_1-f_2\|_{\infty}^{\wedge} \ll N^{1-2(\delta_1/10)^{4}},
    \end{align*}
	then for $\epsilon\gg N^{-(\delta_1/10)^{4}}$ we have
    \begin{align*}
        f_1\approx_{\epsilon} f_2.
	\end{align*}


In view of Definitions~\ref{def_approx} and~\ref{def:Fouriernorm}, we can assume that all involved functions are supported on $n\in (N/2,N]$ only.

Let $\eta=N^{-2(\delta_1/10)^4}$. Write $f=f_1-f_2$ and let $g:(N/2,N]\to \mathbb{C}$ be any function. By the assumption of the lemma we have
	\begin{align}\label{eq1b}
	   \sup_{\alpha \in \mathbb{R}}\left|\sum_{N/2<n\leq  N}f(n)e(\alpha n)\right|\leq \eta N.    
	\end{align}
	We will show that for all but at most $\eta^{2/3} N$ integers $m\in [5N/4,7N/4]$, we have
	\begin{align*}
	   |f*g(m)|\leq \eta^{2/3} N^{1/2}\|g\|_2.  
	\end{align*}
    This implies the lemma: the exceptional count $\eta^{2/3}N=N^{1-\frac43(\delta_1/10)^4}\le N^{1-(\delta_1/10)^4}$ is within the allowance of Definition~\ref{def_approx}, as the functions required for Definition~\ref{def_approx} fulfil $\|g\|_2\leq N^{1/2+o(1)}$.

    Let $\mathcal{S}\subset [5N/4,7N/4]$ be the set of $m$ for which
	\begin{align*}
    	|f*g(m)|>  \eta^{2/3} N^{1/2}\|g\|_2.
	\end{align*}
	Pick unimodular complex numbers $c_m$ such that
	\begin{align*}
    	c_m(f*g(m))> \eta^{2/3} N^{1/2}\|g\|_2 
	\end{align*}
	for $m\in \mathcal{S}$. 

	Then, summing over $m\in [5N/4,7N/4]$ and applying the orthogonality of characters, we obtain
	\begin{align}\begin{split}\label{eq2}
    	\eta^{2/3} N^{1/2}\|g\|_2|\mathcal{S}|&<\sum_{n_1,n_2\in (N/2,N]}f(n_1)g(n_2)c_{n_1+n_2}\mathbf{1}_{\mathcal{S}}(n_1+n_2)\\
		&= \int_{0}^{1} F(\alpha)G(\alpha)S(-\alpha) \, \,\mathrm{d} \alpha, 
        \end{split}
	\end{align}
	where
	\begin{align*}
		F(\alpha)&\coloneqq \sum_{N/2<n\leq  N}f(n)e(n\alpha),\\
		G(\alpha)&\coloneqq \sum_{N/2<n\leq N}g(n)e(n\alpha),\\
		S(\alpha)&\coloneqq \sum_{n}c_n\mathbf{1}_{\mathcal{S}}(n)e(n\alpha).
	\end{align*}

	Now, by the assumption~\eqref{eq1b}, we can apply Cauchy--Schwarz and Parseval's identity to~\eqref{eq2} to conclude that
	\begin{align*}
		\eta^{2/3} N^{1/2}\|g\|_2|\mathcal{S}|&\leq \eta N\left(\int_{0}^1 |G(\alpha)|^2\, \,\mathrm{d}\alpha\right)^{1/2} \left(\int_{0}^1 |S(\alpha)|^2\, \,\mathrm{d}\alpha\right)^{1/2}\\
		&\leq \eta N \|g\|_2|\mathcal{S}|^{1/2}.
	\end{align*}
	This implies
	\begin{align*}
		|\mathcal{S}|\leq  \eta^{2/3} N,
	\end{align*}
	as desired.

\label{lem_twistsievechar}
    Let $f\colon \mathbb{N}\to \mathbb{C}$ be of the form $f(n)=1\star \lambda (n)=\sum_{d\mid n}\lambda(d)$ for some arithmetic function $\lambda$. Let $\chi$ be a primitive Dirichlet character of conductor $r\in \mathbb{N}$. Then for any arithmetic function $g$, we have
	\begin{align*}
		\|fg\|_{\infty}^{\wedge} &\leq \|\lambda \|_1 \|g\|_{\infty}^{\wedge} \\
		\|\chi g\|_{\infty}^{\wedge} &\leq \sqrt{r} \|g\|_{\infty}^{\wedge}. 
	\end{align*}

By the definition of the Fourier norm, we can assume that $g$ is supported on $(N/2,N]$ and in particular any sum over $g(n)$ is convergent. 
We open the definition of $f$ to get
    \begin{align*}
        \sup_{\alpha\in \mathbb{R}} \left| \sum_{n} f(n)g(n)e(\alpha n)\right|&=\sup_{\alpha}\left|\sum_{d}\lambda(d) \sum_{n\equiv 0 \pmod d} g(n) e(\alpha n)\right|\\
        &=\sup_{\alpha\in \mathbb{R}} \left| \sum_{d}\frac{\lambda(d)}{d}\sum_{b(d)} \sum_{n} g(n) e((\alpha+b/d)n)\right|\\
        &\leq \sum_{d}|\lambda(d)|\sup_{\alpha\in \mathbb{R}} \left| \sum_{n} g(n) e(\alpha n)\right|\\
        &= \|\lambda \|_1 \|g\|_{\infty}^{\wedge}.
    \end{align*}
    For the second statement, we use the well known estimate for Gauss sums that gives for primitive characters 
    \begin{align*}
        \max_{b(r)}\bigl|\sum_{a(r)}\chi(a) e_r(ab)\bigr|\leq r^{1/2}.
    \end{align*}
    Indeed, this follows for $(b,r)=1$ from~\cite[Lemma 5.1]{mv} and for $(b,r)\neq 1$, the sum vanishes. Thus, 
     \begin{align*}
        \sup_{\alpha\in \mathbb{R}} \left| \sum_{n} \chi(n)g(n)e(\alpha n)\right|&=  \sup_{\alpha\in \mathbb{R}} \left| \frac{1}{r}\sum_{b(r)} \sum_{a(r)} \chi(a) e_r(-ab) \sum_{n} g(n)e((\alpha+b/r) n) \right|\\
        &\leq \frac{1}{r} \sum_{b(r)} \left|\sum_{a(r)}\chi(a)e_r(-ab) \right| \sup_{\beta \in {\mathbb R}} \left|  \sum_{n} g(n)e(\beta n) \right|\\
        &\leq \sqrt{r} \|g\|_{\infty}^{\wedge}.
    \end{align*}
    This completes the proof.

\begin{align*}
        \sup_{\alpha\in \mathbb{R}} \left| \sum_{n} f(n)g(n)e(\alpha n)\right|&=\sup_{\alpha}\left|\sum_{d}\lambda(d) \sum_{n\equiv 0 \pmod d} g(n) e(\alpha n)\right|\\
        &=\sup_{\alpha\in \mathbb{R}} \left| \sum_{d}\frac{\lambda(d)}{d}\sum_{b(d)} \sum_{n} g(n) e((\alpha+b/d)n)\right|\\
        &\leq \sum_{d}|\lambda(d)|\sup_{\alpha\in \mathbb{R}} \left| \sum_{n} g(n) e(\alpha n)\right|\\
        &= \|\lambda \|_1 \|g\|_{\infty}^{\wedge}.
    \end{align*}

\begin{align*}
        \sup_{\alpha\in \mathbb{R}} \left| \sum_{n} \chi(n)g(n)e(\alpha n)\right|&=  \sup_{\alpha\in \mathbb{R}} \left| \frac{1}{r}\sum_{b(r)} \sum_{a(r)} \chi(a) e_r(-ab) \sum_{n} g(n)e((\alpha+b/r) n) \right|\\
        &\leq \frac{1}{r} \sum_{b(r)} \left|\sum_{a(r)}\chi(a)e_r(-ab) \right| \sup_{\beta \in {\mathbb R}} \left|  \sum_{n} g(n)e(\beta n) \right|\\
        &\leq \sqrt{r} \|g\|_{\infty}^{\wedge}.
    \end{align*}

\label{def_major}
    Define the \emph{major arcs} of order $R\geq 1$ by
	\begin{align*}
	   \mathfrak{M}(R)\coloneqq [0,1)\cap \bigcup_{1\leq q\leq R}\bigcup_{\substack{b\in  \mathbb{Z}\\(b,q)=1}}\left[\frac{b}{q}-\frac{R}{N},\frac{b}{q}+\frac{R}{N}\right] 
	\end{align*}
	and the \emph{minor arcs} by
	\begin{align*}
	   \mathfrak{m}(R)\coloneqq [0,1)\setminus \mathfrak{M}(R).
	\end{align*}
    We also write 
    \begin{align*}
         \|f\|_{\mathfrak{M}(R)}^{\wedge}&\coloneqq\sup_{\alpha \in \mathfrak{M}(R)}\left|\sum_{N/2<n\leq N}f(n)e(\alpha n)\right|,\\
         \|f\|_{\mathfrak{m}(R)}^{\wedge}&\coloneqq\sup_{\alpha \in \mathfrak{m}(R)}\left|\sum_{N/2<n\leq N}f(n)e(\alpha n)\right|.
    \end{align*}

\label{def:bdef}
	Let $G$ be a fixed smooth and non-negative function that is supported in $[-2,2]$ and is equal to $1$ in $[0,1]$, and let $R\geq 2$. Define
	\begin{align*}
	b_R(n)\coloneqq\sum_{r\geq 1}\,\,\,\sideset{}{^{\ast}}\sum_{b\pmod r}e_r(bn)\mathbf{1}_{|n|\leq N/R^4}\frac{R^4}{2N}G\bigl(\frac{\log r}{\log R}\bigr).
\end{align*}

\label{lem:bRextract}
	Let $f$ be any arithmetic function supported on $(N/2,N]$, and assume that $2\leq R\leq N^{1/11}$. We have
	\begin{align*}
	   \|f-f*b_R\|_{\infty}^{\wedge} \ll \|f\|_{\mathfrak{m}(R)}^{\wedge}+\frac{\|f\|_1}{R}+ \frac{\|f\|_\infty N \log R}{R^2}.
	\end{align*}

We first note that by the support condition of $f$ and Definition~\ref{def:bdef}, we have the trivial upper bound
\begin{align*}
    |f*b_R(n)|=&\bigl| \sum_{n_1+n_2=n}f(n_1) b_R(n_2) \bigr|\\
    \leq & \|f\|_\infty \mathbf{1}_{n\in (N/2-N/R^4,N+N/R^4]} \frac{R^4}{2N} \sum_{|n-n_1|\leq N/R^4} \sum_{r\leq R^2} |c_r(n-n_1)|\\
    \ll & \|f\|_\infty \mathbf{1}_{n\in (N/2-N/R^4,N+N/R^4]}R^2 \log R.
\end{align*}
Here we used $|c_r(n_2)|\leq (r,n_2)$ with $n_2=n-n_1$, and that the bound $\sum_{r\leq R^2}|c_r(n_2)|\ll R^2\log R$ holds on average over the range $|n_2|\leq N/R^4$ present in the display. Indeed, writing $(r,n_2)=\sum_{d\mid (r,n_2)}\varphi(d)$ and summing over $n_2$ first,
\begin{align*}
\sum_{|n_2|\leq N/R^4}\ \sum_{r\leq R^2}(r,n_2)
=\sum_{r\leq R^2}\sum_{d\mid r}\varphi(d)\!\!\sum_{\substack{|n_2|\leq N/R^4\\ d\mid n_2}}\!\!1
\ll \frac{N}{R^4}\sum_{r\leq R^2}\sum_{d\mid r}\frac{\varphi(d)}{d}
= \frac{N}{R^4}\sum_{d\leq R^2}\frac{\varphi(d)}{d}\Bigl\lfloor\frac{R^2}{d}\Bigr\rfloor
\ll \frac{N}{R^4}\,R^2\log R,
\end{align*}
using $\sum_{d\leq R^2}\varphi(d)/d^2\leq\sum_{d\leq R^2}1/d\ll\log R$. Multiplying by the prefactor $R^4/(2N)$ gives the pointwise bound $\|f\|_\infty R^2\log R$.
We use this to estimate
\begin{align*}
   &\Bigl|\sum_{n}(f*b_R)(n)e(\alpha n)-\sum_{N/2<n\leq N}(f*b_R)(n)e(\alpha n)\Bigr|\\
   \leq& \sum_{n\leq N/2}|(f*b_R)(n)|+\sum_{n>N}|(f*b_R)(n)|\\
  \ll&  \frac{\|f\|_\infty N \log R}{R^2}.
\end{align*}
Thus, up to an admissible error we can replace 
\begin{align*}
    \sum_{N/2<n\leq N} (f*b_R)(n)e(\alpha n)
\end{align*}
by 
\begin{align*}
    \sum_{n} (f*b_R)(n)e(\alpha n)=\widehat{f}(\alpha) \widehat{b}_R(\alpha).
\end{align*}
Here $\widehat{f}$ is the unrestricted Fourier transform, which agrees with the one of Definition~\ref{def:Fouriernorm} because $f$ is supported on $(N/2,N]$.
Consequently, the lemma follows if we can show that
    \begin{align}\label{eq_bresult}
	   \widehat{b}_R(\alpha)=\begin{cases}1+O(1/R) &\text{ if } \alpha \in \mathfrak{M}(R)\\
		O(1) &\text{ if } \alpha \in \mathfrak{m}(R).
	\end{cases}
	\end{align}

    Given $\alpha\in \mathbb{R}$, let $a\in {\mathbb Z}, q\in {\mathbb N}$ be such that $|a/q-\alpha|$ is minimal among all choices with $(a,q)=1, q\leq R^2$. Write $\beta=\alpha-a/q$ so that
	\begin{align}\label{eq_bdiss}
	   \widehat{b}_R(\alpha)=\frac{R^4}{2N} G\bigl(\frac{\log q}{\log R}\bigr)\sum_{|n|\leq N/R^4}e(-\beta n)+\sum_{r\geq 1}\sum_{\substack{1\leq b<r\\ (b,r)=1 \\ b/r\neq a/q}} G\bigl(\frac{\log r}{\log R}\bigr) \frac{R^4}{2N}\sum_{|n|\leq N/R^4} e\bigl( (\alpha-b/r)n\bigr).
	\end{align}
	As the points $b/r$ with $(b,r)=1$ and $r\leq R^2$ are $1/R^4$ well spaced, in the second sum on the right-hand side of~\eqref{eq_bdiss} we have $|\alpha-b/r|\gg 1/R^4$ and can estimate it by
	\begin{align*}
	   \left|\sum_{r\geq 1}\sum_{\substack{1\leq b<r\\ (b,r)=1 \\ b/r\neq a/q}}  G\bigl(\frac{\log r}{\log R}\bigr) \frac{R^4}{2N}\sum_{|n|\leq N/R^4} e\bigl( (\alpha-b/r)n\bigr)\right|
	   &\ll \sum_{r\geq 1} G\bigl(\frac{\log r}{\log R}\bigr)\frac{R^4}{2N} \bigl(R^4+\sum_{1\leq b\leq r}\frac{r}{b}\bigr)\\
	   &\ll \frac{R^8}{N}\sum_{r\leq R^2} G\bigl(\frac{\log r}{\log R}\bigr)\\
	   &\ll \frac{R^{10}}{N}\\
	   &\ll \frac{1}{R},
	\end{align*}
