	\begin{align}
		\Lambda_{R,r}(n)&=\sum_{d\mid n}d\mu(d)\sum_{\substack{q\equiv 0\pmod d\\ (q,r)=1}}\frac{\mu(q)^2}{\varphi(q)}G\left(\frac{\log(qr)}{\log R}\right)\nonumber\\
		&=\sum_{\substack{d\mid n\\ (d,r)=1}}\frac{d\mu(d)}{\varphi(d)}\sum_{\substack{\ell \\ (\ell,dr)=1}}\frac{\mu(\ell)^2}{\varphi(\ell)}G\left(\frac{\log (\ell dr)}{\log R}\right),\label{eq:Lambda_Q}
	\end{align}
