  \max_{\alpha \in \mathfrak{m}(R)}\Bigl|\sum_{\substack{N_1/2 < n_1 \leq N_1\\ N/2 < n_1 n_2\leq N}} a_{n_1} b_{n_2}  f_{\textup{M}}(n_1n_2+2) f_{\textup{Pre}}(n_1n_2+2) e(\alpha n_1n_2)\Bigr|\ll N^{1+o(1)} R^{-1/6},
\end{align}

\begin{align}\label{eq:minorII}
     \max_{\alpha \in \mathfrak{m}(R)}\Bigl|\sum_{\substack{N_1/2 < n_1 \leq N_1\\ N_2/2 <  n_2 \leq N_2\\ N/2 < n_1n_2 \le N}} a_{n_1} b_{n_2}  \ f_{\textup{M}}(n_1n_2+2) f_{\textup{Pre}}(n_1n_2+2) e(\alpha n_1n_2)\Bigr|\ll N^{1+o(1)} R^{-1/6},
\end{align}

\begin{align*}
    \ll& N^{o(1)} \max_{\alpha \in \mathfrak{m}(R)} \sum_{r\leq D_{1}D_{\mathrm{M},1}D_{\mathrm{M},2}} \bigg| \sum_{\substack{N/2< n_1 n_2\leq N\\ n_1n_2\equiv -2 \pmod{r}\\ N_1/2<n_1\leq N_1 }} a_{n_1}b_{n_2} e(\alpha n_1n_2) \bigg|\ll N^{1+o(1)} \bigg(\frac{1}{R}+\frac{N_1  D_{1}D_{\mathrm{M},1}D_{\mathrm{M},2}}{N}\bigg)^{1/2},
