\label{lem:roughexceptionalminorarc}
   Let $2\leq (\log N)^{100}<R^2\leq P\leq N^{1/4}$ and $1/2\leq \beta \leq 1$. We have
    \begin{align*}
        \sup_{\alpha\in \mathfrak{m}(R)} \left|\sum_{n\leq N} r_P(n)n^{\beta-1} e(\alpha n)\right|\ll N R^{-1/3}.
    \end{align*}

\begin{align*}
        \sup_{\alpha\in \mathfrak{m}(R)} \left|\sum_{n\leq N} r_P(n)n^{\beta-1} e(\alpha n)\right|\ll N R^{-1/3}.
    \end{align*}

Since
\begin{align}\label{eq:expnbeta}
n^{\beta-1}=1+(\beta-1)\int_{1}^{n}t^{\beta-2}\,\mathrm{d} t,    
\end{align}
and $\int_{1}^{N}t^{\beta-2}\,\mathrm{d} t\ll \log N$, by the triangle inequality it suffices to prove the claim without the $n^{\beta-1}$ factor and with the summation range replaced by $n\leq \xi$ for $\xi\leq N$. We discard the contribution of $n\leq NR^{-1/2}$ trivially, dyadically decompose and apply Lemma~\ref{lem:combdecomp1}, noting that $(N R^{-1/2})^{1/3}>N^{1/4}$. The claim then follows from standard minor arc estimates, see for example~\cite[Lemmas 13.7 and 13.8]{iw-kow}.

 \label{lem_sie1}
    Let $\mathcal{P}$ be a square-free positive integer, $(\lambda_d)_{d\geq 1}$ be a sequence of complex numbers supported on the divisors of $\mathcal{P}$ only and assume that $e\mid\mathcal{P}$. Let $g$ be a multiplicative function such that $0\leq g(p) <1$ for all primes $p$ and $g(p)>0$ for all $p\mid e$, and define a multiplicative function $h$ supported on square-free numbers by $h(p)=\frac{g(p)}{1-g(p)}$.  Then we have
	\begin{align*}
	   g(e)\sum_{d\mid \mathcal{P}/e}\lambda_{de}g(d)=\prod_{p\mid\mathcal{P}}\bigl(1-g(p)\bigr) \mu(e)h(e)\sum_{b\mid\mathcal{P}}\theta(b)h(b) \frac{\mu((b,e))}{h((b,e))},
	\end{align*}
	where $\theta(n)=\sum_{d\mid n}\lambda_d$.

\label{lem_fundlem}
    Let $f\in \{\omega,\Omega\}$ be pre-sieves as in Definition~\ref{def:presieve}, and let $\beta=200$. Write $\mathcal{P}(y)=\prod_{\substack{ 5\leq p< y}}p$ and $\mathcal{P}_r=\mathcal{P}(P_1^{\bigl(\frac{\beta-1}{\beta+1}\bigr)^{r}})$, and assume that $s=\frac{\log D_1}{\log P_1}>\beta+2$. Then we have
	\begin{align*}
	   |f(n)-r_{P_1}(n)|\leq \prod_{p< P_1}\left(1-\frac{1}{p}\right)^{-1}\tau(n)^2\sum_{\substack{r\in \mathbb{N}\\ r>( s-\beta-1)/2}}4^{-r}\mathbf{1}_{(n,\mathcal{P}_r)=1}.
	\end{align*}

The beta sieve is a combinatorial sieve that is constructed by iteration with certain cutoff parameters, see~\cite[equations (6.31)--(6.34), (6.54)]{cribro}.  From this it follows immediately that for the upper bound sieve $\Omega$ we have the identity
	\begin{align*}
	   \Omega(n)=r_{P_1}(n)+ \prod_{p < P_1}\left(1-\frac{1}{p}\right)^{-1}\sum_{r \text{ odd}}V_r(n),
	\end{align*}
	and similarly for the lower bound sieve $\omega$ we have
	\begin{align*}
	   \omega(n)=r_{P_1}(n)- \prod_{p < P_1}\left(1-\frac{1}{p}\right)^{-1}\sum_{r \text{ even}}V_r(n),
	\end{align*}
	where
	\begin{align*}
	   V_r(n)=\sum_{\substack{p_1\cdots p_r \mid n\\ p_i\mid \mathcal{P}(P_1), \,\,\, p_r<p_{r-1}<\ldots <p_1 \\ p_1p_2\cdots p_r p_r^\beta\geq D_1 \\ p_1p_2\cdots p_hp_h^{\beta} <D_1 \text{ for all } h<r, h\equiv r\pmod 2 }}\mathbf{1}_{(n/(p_1\cdots p_r),\mathcal{P}(p_r))=1}.
	\end{align*}
	By~\cite[Corollary 6.6]{cribro}, in the last sum we have $p_r\geq P_1^{\bigl(\frac{\beta-1}{\beta+1}\bigr)^{r/2}}$. We also have $D_1\leq p_1^{r+\beta}\leq P_1^{r+\beta}$, which is impossible unless $r\geq s-\beta$. We complete the proof by repeating the argument in~\cite[after equation (58)]{matoalmost}: In the sum defining $V_r$, the distinct primes $p_i\mid\mathcal{P}(P_1)$ satisfy $p_i\ge5$, so writing $\nu(n)$ for the number of prime divisors of $n$ we have $\nu(n)\geq r$ so that $2^{\nu(n)-r}\geq 1$. Hence,
    \begin{align*}
        V_r(n)\leq \mathbf{1}_{(n,\mathcal{P}_{r/2})=1} 2^{\nu(n)-r} \sum_{k \mid n} 1 \leq  \mathbf{1}_{(n,\mathcal{P}_{r/2})=1} \tau(n)^2 2^{-r}.
    \end{align*}
     Writing $r=2r'+1$ or $r=2r'$, respectively for the case of an upper bound or lower bound sieve, the lemma follows.

\begin{align*}
	   V_r(n)=\sum_{\substack{p_1\cdots p_r \mid n\\ p_i\mid \mathcal{P}(P_1), \,\,\, p_r<p_{r-1}<\ldots <p_1 \\ p_1p_2\cdots p_r p_r^\beta\geq D_1 \\ p_1p_2\cdots p_hp_h^{\beta} <D_1 \text{ for all } h<r, h\equiv r\pmod 2 }}\mathbf{1}_{(n/(p_1\cdots p_r),\mathcal{P}(p_r))=1}.
	\end{align*}

\label{prop_presieveasmyp}
    For $1\leq i \leq 4$, let the functions $f_i\in \{ \omega, \Omega \}$ be pre-sieves as in Definition~\ref{def:presieve}. For any natural number $m$ and any $1\leq X\leq m$, we have
    \begin{align}\label{eq_propsifted_asymptotics}\begin{aligned}
	   &\sum_{n\leq X} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2)\\
       =& X \mathfrak{S}(m)\left(1+ O\left(e^{-\frac{\log D_1}{10 \log P_1}}+\frac{\log m}{P_1 }\right)\right)+O(D_1^4 (\log P_1)^4).
       \end{aligned}
	\end{align}

\begin{align}\label{eq_propsifted_asymptotics}\begin{aligned}
	   &\sum_{n\leq X} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2)\\
       =& X \mathfrak{S}(m)\left(1+ O\left(e^{-\frac{\log D_1}{10 \log P_1}}+\frac{\log m}{P_1 }\right)\right)+O(D_1^4 (\log P_1)^4).
       \end{aligned}
	\end{align}

We write  $\mathcal{P}=\prod_{5\leq p < P_1}p$, 
expand out the sieves $f_i$ according to their definitions, and observe that $(n,6)=1, (n+2,6)=1, (m-n,6)=1, (m-n+2,6)=1$ is equivalent to $m\equiv 4 \pmod 6, n\equiv 5\pmod 6$. This leads to
    \begin{align}
       \nonumber &\sum_{n\leq X} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2) \\
        =& \frac{3^4}{\prod_{p<P_1}(1-1/p)^4} \mathbf{1}_{m\equiv 4\pmod 6} \sum_{d_1,d_2,d_3,d_4\mid\mathcal{P}}  \prod_{i=1}^4\lambda_{i}(d_i)\sum_{\substack{n\leq X\\ d_1\mid n \\ d_2\mid n+2 \\ d_3\mid m-n \\ d_4\mid m-n+2}} \mathbf{1}_{n\equiv 5(6)}. \label{eq_sieveopen}
	\end{align}
    There exists a solution to the divisibility conditions in the innermost sum if and only if 
	\begin{align}
\begin{aligned}
(d_1,d_2)&=1,\\
(d_3,d_4)&=1,\\
(d_1,d_3)&\mid m,\\
(d_1,d_4)&\mid m+2,\\
(d_2,d_3)&\mid m+2,\\
(d_2,d_4)&\mid m+4.
\end{aligned}
\label{eq:conditions}
\end{align}
Let us abbreviate these conditions as $(d_1,d_2,d_3,d_4)\in \mathcal{D}_m$.
	Under these conditions, the sum over $n$ in~\eqref{eq_sieveopen} equals
	\begin{align*}
		\frac{X}{6[d_1,d_2,d_3,d_4]}+O(1).
	\end{align*}
    The $O(1)$ error term contributes to~\eqref{eq_sieveopen} at most $O((\log P_1)^4D_1^4)$ by Mertens' theorem. Hence,~\eqref{eq_sieveopen} becomes 
    \begin{align}\label{eq:sievemainsum}
     \frac{3^4 X}{6\prod_{p<P_1}(1-1/p)^4} \mathbf{1}_{m\equiv 4 \pmod 6}  \sum_{\substack{d_1,d_2,d_3,d_4\mid\mathcal{P}\\ (d_1,d_2,d_3,d_4)\in \mathcal{D}_m}} \frac{\prod_{i=1}^4\lambda_{i}(d_i)}{[d_1,d_2,d_3,d_4]}+ O((\log P_1)^4D_1^4).
    \end{align}
    We want to evaluate the summation over each of the $d_i$ with Lemma~\ref{lem_sie1} and afterwards apply Lemma~\ref{lem_fundlem}. To make this possible we need to carefully disentangle the coprimality and divisibility conditions in order to not lose relative to the size of the expected main term in the error terms.

    In the rest of the proof, we use $\sideset{}{'}\sum$ to indicate that the summation variables are supported on divisors of $\mathcal{P}$ only. Next, write $e_1=(d_1,d_3), e_2=(d_1,d_4), e_3=(d_2,d_3), e_4=(d_2,d_4)$ and further $d_1=d_1'e_1e_2$, $d_2=d_2'e_3e_4$, $d_3=d_3'e_1e_3$, $d_4=d_4'e_2e_4$. Note that this is possible since by $(d_3,d_4)=1$ we have $(e_1,e_4)=1$ (and $(e_2,e_3)=1$ etc.), and by $(d_1,d_2)=1$ we have $(e_1,e_3)=1$ (and so on). Note further that~\eqref{eq:conditions} implies that the variables $d'_i$ and $e_j$ are mutually coprime. Thus, $[d_1,d_2,d_3,d_4]=d_1'd_2'd_3'd_4'e_1e_2e_3e_4$ and the central sum in~\eqref{eq:sievemainsum} becomes
	\begin{align*}
		&\sideset{}{'}\sum_{\substack{d_1, d_2, d_3, d_4\\ (d_1,d_2,d_3,d_4)\in \mathcal{D}_m}}\frac{\prod_{i=1}^4\lambda_{i}(d_i)}{[d_1,d_2,d_3,d_4]}\\
		=&\sideset{}{'}\sum_{\substack{e_1\mid m\\ e_2, e_3\mid  m+2 \\ e_4\mid m+4\\ e_i \text{ coprime}}}\frac{1}{e_1 e_2 e_3 e_4} \sideset{}{'}\sum_{\substack{d_1'\\ (d_1',e_3e_4)=1}} \frac{\lambda_1(d_1'e_1e_2)}{d_1'} \sideset{}{'}\sum_{\substack{d_2' \\ (d_2',d_1'e_1e_2)=1}} \frac{\lambda_2(d_2'e_3e_4)}{d_2'} \\
		&\times\sideset{}{'}\sum_{\substack{d_3' \\ (d_3',d_1'd_2'e_2 e_4)=1}} \frac{\lambda_3(d_3'e_1e_3)}{d_3'} \sideset{}{'}\sum_{\substack{d_4' \\ (d_4',d_1' d_2' d_3' e_1 e_3)=1}} \frac{\lambda_4(d_4'e_2e_4)}{d_4'}.
	\end{align*}
	To ease notation, write $\mathbf{e}=e_1e_2e_3e_4$ and remove the $'$ from the $d_i'$ variables again. The strategy to approach~\eqref{eq:sievemainsum} is to evaluate the sums over $d_4,d_3,d_2,d_1$ in the last display with Lemma~\ref{lem_sie1}, successively exchanging the order of summation. Note that since the function $\theta$ of Lemma~\ref{lem_sie1} associated with a given sequence $\lambda_i$ is $\prod_{p<P_1}(1-1/p) \cdot f_i$, each successive application will cancel one of the $(1-1/p)^{-1}$ factors in~\eqref{eq:sievemainsum}. 

    Starting with the summation over $d_4$, we apply of Lemma~\ref{lem_sie1} with $g(d)=\frac{\mathbf{1}_{(d,d_1d_2d_3e_1 e_3)=1}}{d}$ and $e=e_2 e_4$. This gives us
	\begin{align*}
		& \prod_{p<P_1}\left(1-\frac{1}{p}\right)^{-1}\sideset{}{'}\sum_{\substack{d_4 \\ (d_4,d_1 d_2 d_3 e_1 e_3)=1}} \frac{\lambda_4(d_4e_2e_4)}{d_4} \\
		=& \prod_{p\mid \mathcal{P}/(d_1d_2d_3e_1e_3)}\left(1-\frac{1}{p}\right) \frac{\mu(e_2 e_4) e_2 e_4}{\varphi(e_2 e_4)}  \sideset{}{'}\sum_{\substack{b_4\\ (b_4,d_1 d_2 d_3e_1e_3)=1}}\frac{f_4(b_4)}{\varphi(b_4)} \mu((b_4,e_2 e_4))\varphi((b_4,e_2 e_4))\\
		=&\prod_{p\mid \mathcal{P}}\left(1-\frac{1}{p}\right) \frac{d_1 d_2 d_3 \mathbf{e} \mu(e_2 e_4) }{\varphi(d_1d_2d_3 \mathbf{e})}\sideset{}{'}\sum_{j_4\mid e_2e_4}\mu(j_4)\sideset{}{'}\sum_{\substack{b_4\\ (b_4,d_1d_2d_3\mathbf{e})=1}} \frac{f_4(b_4j_4)}{\varphi(b_4)}.
	\end{align*}
   For $i\in \{2,3,4\}$, we denote by $\varphi_i$ the multiplicative function given on primes $p$ by $p-i$. We only employ this notation for $d\mid \mathcal{P}$, so that $(d,6)=1$ and $d$ is square-free, ensuring $\varphi_i(d)>0$. By an application of Lemma~\ref{lem_sie1}, the relevant $d_3$ sum now is
	\begin{align*}
		&\prod_{p<P_1}\left(1-\frac{1}{p}\right)^{-1}\sideset{}{'}\sum_{\substack{d_3 \\ (d_3,b_4 d_1d_2  e_2 e_4)}}\frac{\lambda_3(d_3e_1e_3)}{\varphi(d_3)}\\
		=&\prod_{p\mid \mathcal{P}}\left(1-\frac{1}{\varphi(p)}\right) \frac{\varphi(d_1 d_2 b_4 \mathbf{e})\mu(e_1 e_3) }{\varphi_2(d_1d_2b_4\mathbf{e})} \sideset{}{'}\sum_{j_3\mid e_1e_3}\mu(j_3)\sideset{}{'}\sum_{\substack{b_3\\ (b_3,d_1 d_2 b_4 \mathbf{e})=1}}\frac{f_3(b_3j_3)}{\varphi_2(b_3)}.
		\end{align*}
	The $d_2$ sum becomes 
	\begin{align*}
		& \prod_{p<P_1}\left(1-\frac{1}{p}\right)^{-1}\sideset{}{'}\sum_{\substack{d_2 \\ (d_2,d_1b_3 b_4 e_1e_2)=1}} \frac{\lambda_2(d_2e_3e_4)}{\varphi_2(d_2)} \\
		=&\prod_{p\mid \mathcal{P}}\left(1-\frac{1}{\varphi_2(p)}\right) \frac{\varphi_2(d_1b_3b_4e_1e_2e_3e_4)\mu(e_3 e_4) }{\varphi_3(d_1b_3b_4e_1e_2e_3e_4)} \sideset{}{'}\sum_{j_2\mid e_3e_4}\mu(j_2) \sideset{}{'}\sum_{\substack{b_2\mid \mathcal{P}\\ (b_2,d_1 b_3 b_4\mathbf{e})=1}}\frac{f_2(b_2j_2)}{\varphi_3(b_2)}.
	\end{align*}
	Finally, for the $d_1$ sum we get 
	\begin{align*}
		&\prod_{p<P_1}\left(1-\frac{1}{p}\right)^{-1}\sideset{}{'}\sum_{\substack{d_1\\ (d_1,b_2 b_3 b_4 e_3e_4)=1}} \frac{\lambda_1(d_1e_1e_2)}{\varphi_3(d_1)}\\
		=&\prod_{p\mid \mathcal{P}}\left(1-\frac{1}{\varphi_3(p)}\right)\frac{\varphi_3(b_2b_3b_4\mathbf{e})\mu(e_1 e_2) }{\varphi_4(b_2b_3b_4\mathbf{e})} \sideset{}{'}\sum_{j_1\mid e_1e_2}\mu(j_1)\sideset{}{'}\sum_{\substack{b_1\\ (b_1,b_2 b_3 b_4\mathbf{e})=1}}\frac{f_1(b_1j_1)}{\varphi_4(b_1)}.
		\end{align*}
	Note that for $p\geq 5$
	\begin{align*}
		\left(1-\frac{1}{p}\right)    \left(1-\frac{1}{\varphi(p)}\right)\left(1-\frac{1}{\varphi_2(p)}\right)\left(1-\frac{1}{\varphi_3(p)}\right)=1-\frac{4}{p}.
	\end{align*}
	Combining the four evaluations and recalling the normalisation of the $f_i$, we get for the term of interest in~\eqref{eq:sievemainsum} the identity
	\begin{align}
    \nonumber & \frac{3^4}{6} X\mathbf{1}_{m\equiv 4 \pmod 6} \frac{1}{\prod_{p<P_1}(1-1/p)^4}  \sum_{\substack{d_1,d_2,d_3,d_4\mid\mathcal{P}\\ (d_1,d_2,d_3,d_4)\in \mathcal{D}_m}} \frac{\prod_{i=1}^4\lambda_{i}(d_i)}{[d_1,d_2,d_3,d_4]}\\
		\nonumber=& \frac{3^4}{6} X\mathbf{1}_{m\equiv 4 \pmod 6} \prod_{p\mid \mathcal{P}}\left(1-\frac{4}{p}\right)\sideset{}{'}\sum_{\substack{e_1\mid m\\ e_2, e_3\mid  m+2 \\ e_4\mid m+4 \\ e_i \text{ coprime}}}\frac{1}{\varphi_4(\mathbf{e})}   \\
		& \times \sideset{}{'}\sum_{\substack{j_1\mid e_1e_2\\ j_2\mid e_3e_4\\ j_3\mid e_1e_3\\ j_4\mid e_2 e_4}}\sideset{}{'}\sum_{\substack{b_i\\ (b_i,b_j)=1,\,\forall i\neq j\\ (b_i,\mathbf{e})=1}} \mu(j_1)\mu(j_2)\mu(j_3)\mu(j_4)\frac{f_1(b_1j_1)f_2(b_2j_2)f_3(b_3j_3)f_4(b_4j_4)}{\varphi_4(b_1b_2b_3b_4)}. \label{eq:ebjsum}
	\end{align}
	Write $\mathbf{b}=b_1b_2b_3b_4$ and $\mathbf{j}=j_1j_2j_3j_4$. The term with $\mathbf{b}\mathbf{j}=1$ in~\eqref{eq:ebjsum} is the main term. Since $\mathcal{P}$ is coprime to the primes less than $5$, we have
    \begin{align}\label{eq:sums}
