   \begin{align*}
       \sum_{\substack{d\mid n\\,\mathrm{d}\leq D}}\lambda_d^{-} \leq  \mathbf{1}_{(n,\prod_{p\leq P}p)=1}\leq \sum_{\substack{d\mid n\\,\mathrm{d}\leq D}}\lambda_d^{+},  
   \end{align*}
   so for $v\in \{-1,+1\}$ we have
   \begin{align*}
       \sum_{\substack{d\mid n\\,\mathrm{d}\leq D}}\lambda_d^{-}\mathbf{1}_{\widetilde{\chi}(n)=v} \leq  \mathbf{1}_{(n,\prod_{p\leq P}p)=1}\mathbf{1}_{\widetilde{\chi}(n)=v}\leq \sum_{\substack{d\mid n\\,\mathrm{d}\leq D}}\lambda_d^{+}\mathbf{1}_{\widetilde{\chi}(n)=v} . 
   \end{align*}
    Hence, for any $v\in \{-1,+1\}$ and any interval $I\subset [1,N]$ with $|I|\geq N^{9/10}$, by the P\'olya--Vinogradov inequality and the fundamental lemma of the linear sieve~\cite[eq. (11.134) and Theorem 11.13]{cribro} we have
   \begin{align*}
       \sum_{n\in I}\mathbf{1}_{(n,\prod_{p\leq P}p)=1}\mathbf{1}_{\widetilde{\chi}(n)=v}&\leq \sum_{d\leq D}\lambda_d^{+}\sum_{\substack{n\in I\\,\mathrm{d}\mid n}}\mathbf{1}_{\widetilde{\chi}(n)=v}\\
