       &=\frac{\varphi(\widetilde{r})}{\widetilde{r}}\sum_{d\leq D}\lambda_d^{+}\frac{|I|}{d}+O(\widetilde{r}D)+O(D R^{1/2}\log R)\\
       &=\frac{\varphi(\widetilde{r})}{\widetilde{r}}\left(1+O\left(\exp\left(-\frac{1}{2}\frac{\log N}{\log P}\right)\right)\right)\prod_{p\leq P}\left(1-\frac{1}{p}\right)|I|.
   \end{align*}
