\label{prop:LLR}
    Let $\exp((\log N)^{1/2})\leq R \leq N^{1/200}$ and let $\Lambda^*\in\{\Lambda, \Lambda_{E_3^*}\}$. There exists an arithmetic function $E$  such that the following hold.
	\begin{enumerate}
	   \item If there is no exceptional zero of level $R^2$ and quality $\kappa$, then we have
		\begin{align}\label{eq:LLR1}
		  \|\Lambda^{*}-\Lambda_{R,1}-E\|_{\infty}^{\wedge}\ll N R^{-1/3}
		\end{align}
	    and
	   \begin{align}
             \label{eq:LLR101} |E(n)|&\ll H_R(n)\exp\bigl( -c \kappa \frac{\log N}{\log R} \bigr).
	   \end{align}
		\item If there is an exceptional zero $\widetilde{\beta}$ of level $R^2$ and quality $\kappa$ with exceptional character $\widetilde{\chi}$, then we have
			\begin{align}\label{eq:LLRfouerror}
				\|\Lambda^{*}-\Lambda_{R,1}(1-(\cdot)^{\widetilde{\beta}-1}\widetilde{\chi})+E\|_{\infty}^{\wedge}\ll N (R^{-1/3}+ R^{-1+o(1)}\widetilde{r}^{3/2})
			\end{align}
             and
	       \begin{align}	\label{eq:LLRexcerror}
              |E(n)|&\ll H_R(n) (1-\widetilde{\beta})(\log N)\exp\bigl(-c\frac{\log N}{\log R}\bigr).
			\end{align}
	\end{enumerate}

Let us first consider the unexceptional case. Recall the definition of $b_R$ in Definition~\ref{def:bdef}. 
    By Lemma~\ref{lem:bRextract}, the combinatorial decomposition in Lemma~\ref{lem:combdecomp1} and standard minor arc bounds~\cite[Lemma 13.7, 13.8]{iw-kow}, we have for $\Lambda^*\in \{\Lambda, \Lambda_{E_3^*}\} $ the bound
    \begin{align}\label{eq:roughappr2}
        \|\Lambda^*- \Lambda^* * b_{R}\|^{\wedge}_\infty &\ll N R^{-1/3}.
    \end{align}
    Of course, with slightly weaker $R$ dependence this also follows immediately from Lemma~\ref{lem:minor}.

Recall the definition of $\Lambda_{R,r}$ in~\eqref{eq:LRrdef} and let
\begin{align*}
    E_0(n):=&\sum_{n_1+n_2=n} b_R(n_1) \Lambda(n_2) 1_{p|n_2 \Rightarrow p\leq R^2}\\
