    \begin{align*}
        \Lambda^* *b_{R}(n)&=\sum_{r\leq R^2}\,\,\,\sideset{}{^{\ast}}\sum_{\chi\pmod r} \chi(n)\frac{r}{\varphi(r)} \Lambda_{R,r}(n) \frac{\sum_{|n'-n|\leq N/R^4}  \Lambda^*(n')\overline{\chi}(n')}{2N/R^4}+E_0(n)\\
        &=\Lambda_{R,1}(n) + E_1(n)+E_0(n),
    \end{align*}
    where
    \begin{align*}
         E_1(n)=\sum_{r\leq R^2}\,\,\,\sideset{}{^{\ast}}\sum_{\chi\pmod r} \chi(n)\frac{r}{\varphi(r)} \Lambda_{R,r}(n)  \frac{\sum_{|n'-n|\leq N/R^4} (\Lambda^*(n')\overline{\chi}(n')-\mathbf{1}_{r=1})}{2N/R^4}.
