    \end{align}
     By Lemma~\ref{lem_twistsievechar} we have
    \begin{align*}
        \|\widetilde{\chi} (\cdot)^{\widetilde{\beta}-1}E_4 \|^{\wedge}_\infty \ll \sqrt{\widetilde{r}}\|(\cdot)^{\widetilde{\beta}-1}E_4  \|^{\wedge}_\infty.
    \end{align*}    We then estimate the Fourier transform of $(\cdot)^{\widetilde{\beta}-1}E_4$ at $\alpha \in \mathbb{R}$ as
