			\end{align}
             Here $E$ fulfils again~\eqref{eq:rLR101}, and now additionally
	       \begin{align}	\label{eq:rLRexcerror}
              \mathbf{1}_{\chi(n)=1}|E(n)|&\ll H_R(n) (1-\beta)(\log N)\Bigl(\frac{\log N}{\log P}\exp\left(-c\frac{\log P }{\log R}\right)+\exp\left(-c\frac{\log N }{\log P}\right) \Bigr).
