    The proof of~\eqref{eq:rLR1} and~\eqref{eq:rLR101} is identical to the one of Proposition~\ref{prop:LLR} in the unexceptional case, apart from using Lemma~\ref{le:gallagher_rough}, applied with $R^4$ in place of $R$, here.

To prove the statements involving a quadratic character, let 
    $f_1(n)=r_{P}(n)(1-\chi(n)n^{\beta-1})$. We first approximate this by $f_2(n)=(1-\chi(n)n^{\beta-1})(r_P*b_{R})(n)$ and claim that
    \begin{align}\label{eq:roughapproxf1f2}
        \|f_1-f_2\|^{\wedge}_\infty \ll N R^{-1/3} \sqrt{r}.
    \end{align}
    By the triangle inequality
    \begin{align*}
         \|f_1-f_2\|^{\wedge}_\infty\leq \|r_P-r_P*b_R\|^{\wedge}_\infty+ \|(\cdot)^{\beta-1}\chi\cdot (r_P-r_P*b_R)\|^{\wedge}_\infty.
    \end{align*}
    By a standard minor arc bound based on Lemma~\ref{lem:combdecomp1} and~\cite[Lemmas 13.7 and 13.8]{iw-kow}, the first part is acceptably small. To estimate the second term on the right, we  remove the character with Lemma~\ref{lem_twistsievechar} and move the weight  $n^{\beta-1}$ inside the convolution. By Lemma~\ref{le:smoothconvo} with $\psi(n)=n^{\beta-1}$ and the upper bound 
    \begin{align*}
        \|\psi'\mathbf{1}_{[N/3,2N]}\|_\infty\leq N^{-1}
    \end{align*}
    we then have 
    \begin{align*}
        \|(\cdot)^{\beta-1}\chi\cdot (r_P-r_P*b_R)\|^{\wedge}_\infty \ll \sqrt{r} \Bigl(\|r_P (\cdot)^{\beta-1}-r_P(\cdot)^{\beta-1}*b_R\|^{\wedge}_\infty+NR^{-1}\Bigr).
    \end{align*}
    The remaining Fourier norm is sufficiently small by Lemmas~\ref{lem:bRextract} and~\ref{lem:roughexceptionalminorarc}. The bound~\eqref{eq:roughapproxf1f2} follows.

    We now consider $f_2$. We rewrite the convolution with multiplicative characters as in~\eqref{eq:f*b} and extract an error term to get
    \begin{align}\label{eq:roughapproxf2exp}
        f_2(n)=(1-\chi(n)n^{\beta-1})\Lambda_{R,1}(n)+E_2(n),
    \end{align}
    where 
    \begin{align*}
        E_2(n)=(1-\chi(n)n^{\beta-1})\sum_{q\leq R^2}\,\,\,\sideset{}{^{\ast}}\sum_{\psi\pmod {q}}\psi(n)\frac{q}{\varphi(q)} \Lambda_{R,q}(n) \frac{\sum_{|n'-n|\leq N/R^4}( r_{P}(n')\overline{\psi}(n')-\mathbf{1}_{q=1})}{2N/R^4}.
