    Observe that  \begin{align*}
        \mathbf{1}_{\chi(n)=1}(1-\chi(n)n^{\beta-1})\leq 1-n^{\beta-1}\ll (1-\beta)\log N,
    \end{align*}
    so that an application  of Lemmas~\ref{lem:LRupper} and~\ref{le:gallagher_rough}, applied with $R^4$ in place of $R$, for the terms $2\le q\le R^2$, together with the mean-value estimate for $r_P$ bounding the $q=1$ term by $H_R(n)\exp(-c\log N/\log P)$, shows that
    \begin{align*}
    |E_2(n)|\ll& H_R(n) \Bigl(\frac{\log N}{\log P}\exp\left(-c\frac{\log P }{\log R}\right)+\exp\left(-c\frac{\log N }{\log P}\right)\Bigr)\\
         \mathbf{1}_{\chi(n)=1}|E_2(n)|\ll& H_R(n) (1-\beta)\log N\Bigl(\frac{\log N}{\log P}\exp\left(-c\frac{\log P }{\log R}\right)+\exp\left(-c\frac{\log N }{\log P}\right) \Bigr).
    \end{align*}
    This implies that $E_2$ satisfies both~\eqref{eq:rLR101} and~\eqref{eq:rLRexcerror}.

