    if $\delta_1$ is small enough in absolute terms. This implies the proposition, after recalling that in Definition~\ref{def_approx} the companion function $g(n)$ is majorised in absolute value by $\Omega(n)\Omega(n+2)$.

\label{prop_reducetoroughexc} 
     Let $P_0=N^{\delta_1},R_0=N^{\delta_1^3},P_1=N^{\delta_1^4},D_1=N^{\delta_1^3/100},$ $\lambda$ the constant from Lemma~\ref{lem_excmodulussize} and let $f\in\{\omega,\Omega\}$ be a pre-sieve as in Definition~\ref{def:presieve}. Assume that $\widetilde{\chi}$ is the exceptional character with exceptional zero $\widetilde{\beta}$ of quality $\lambda \delta_1^2$ and level $R_0^2$. Then for any $\epsilon>e^{-c \delta_1^{-1/2}}$, we have
    \begin{align*}
	   \mathbf{1}_{\widetilde{\chi}(n)=-1}\Lambda(n)f(n+2)&\approx_{\epsilon}  \mathbf{1}_{\widetilde{\chi}(n)=-1}(1+n^{\widetilde{\beta}-1}) r_{P_0}(n)f(n+ 2),\\
	   \mathbf{1}_{\widetilde{\chi}(n)=-1}f(n)\Lambda_{E_3^*}(n+2)&\approx_{\epsilon} c_{E_3^*}  \mathbf{1}_{\widetilde{\chi}(n)=-1}f(n)(1-\widetilde{\chi}(n+2)n^{\widetilde{\beta}-1})r_{P_0}(n+2).
	\end{align*}
	Further, for $\widetilde{\epsilon}>(1-\widetilde{\beta})(\log N)e^{-c \delta_1^{-1/2}}$, it holds that
	\begin{align*}
		\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}\Lambda(n)f(n+2)&\approx_{\widetilde{\epsilon}} \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}(1-n^{\widetilde{\beta}-1} )r_{P_0}(n)f(n+2),\\
		\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}f(n)\Lambda_{E_3^*}(n+2)&\approx_{\widetilde{\epsilon}} \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}(1-n^{\widetilde{\beta}-1})f(n) r_{P_0}(n+2) .
	\end{align*}

We again only handle the case of $\Lambda(n)f(n+2)$, the others being similar (noting that $(n+2)^{\widetilde{\beta}-1}$ can be replaced by $n^{\widetilde{\beta}-1}$ with respect to $\approx$ by Taylor expansion). We start with the observation that $\mathbf{1}_{\widetilde{\chi}(n)=\pm 1}=\frac{1}{2}(1\pm \widetilde{\chi}(n))$ that holds for $(n,\widetilde{r})=1$ and write $\mathfrak{c}(n)$ for $\mathbf{1}_{\widetilde{\chi}(n)=-1}$ or $\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}$ and $\mathfrak{d}(n)=1-\widetilde{\chi}(n)n^{\widetilde{\beta}-1}$. Note that higher prime powers can be again discarded easily. 

By Lemma~\ref{lem_excmodulussize} we can assume that the exceptional modulus is bounded by $\widetilde{R}=N^{2\delta_1^5}$. We use this bound to apply the exceptional case of Theorem~\ref{thm:gallagher_application} with $P=P_0=N^{\delta_1}, R=R_0=N^{\delta_1^3}$ together with Lemma~\ref{lem_twistsievechar} and Lemma~\ref{lem_excmodulussize} to get 
\begin{align*}
     \|\mathfrak{c}f^+(\Lambda - r_{P_0}\mathfrak{d}+E)\|^{\wedge}_\infty &\ll \widetilde{R}^2 D_1  N R_0^{-1/3} =  N^{1+4 \delta_1^5+\delta_1^3/100-\delta_1^3/3} \ll N^{1-\delta_1^3/4},
\end{align*}
where $E(n)$ can be estimated by~\eqref{eq:roughapprexcerror}. By Lemma~\ref{lem_fourierimpliesapprox}, we have
\begin{align*}
    \mathfrak{c}(n)\Lambda(n)f(n+2)\approx_{\epsilon'} \mathfrak{c}(n) r_{P_0}
    (n)\mathfrak{d}(n)+\mathfrak{c}(n)E(n)f(n+2).
\end{align*}
for any $\epsilon'>N^{-\delta_1^{4}}$. This is acceptable, as both $\epsilon$ and $\widetilde{\epsilon}$ are larger than the lower bound for $\epsilon'$ by~\eqref{eq:exczerolowerbound}.

In the case $\mathfrak{c}(n)=\mathbf{1}_{\widetilde{\chi}(n)=-1}$ we have
\begin{align*}
   \mathfrak{c}(n)\mathfrak{d}(n)=\mathbf{1}_{\widetilde{\chi}(n)=-1}(1+n^{\widetilde{\beta}-1}),
\end{align*}
and we trivially bound
\begin{align*}
    |\mathbf{1}_{\widetilde{\chi}(n)=-1}E(n)|\leq |E(n)|.    
\end{align*}
So, just as in the unexceptional case (see proof of Proposition~\ref{prop_reducetorough}),  we get
\begin{align*}
    \mathfrak{c}(n)E(n)f(n+2)\approx_{\epsilon} 0
\end{align*}
in the required range of $\epsilon$. 

In the case $\mathfrak{c}(n)=\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}$ we have
\begin{align*}
  \mathfrak{c}(n)\mathfrak{d}(n)=1-n^{\widetilde{\beta}-1},
\end{align*}
and we can make use of the improved error in~\eqref{eq:roughapprexcerror} to get
\begin{align*}
    \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}E(n)f(n+2)\approx_{\widetilde{\epsilon} }0.
\end{align*}

\begin{align*}
         \|\mathfrak{c}f^+(\Lambda - r_{P_0}\mathfrak{d}+E)\|^{\wedge}_\infty &\ll \widetilde{R}^2 D_1  N R_0^{-1/3} =  N^{1+4 \delta_1^5+\delta_1^3/100-\delta_1^3/3} \ll N^{1-\delta_1^3/4},
    \end{align*}

\label{lem_finalunex}
    Let $P_1=N^{\delta_1^4},R_0=N^{\delta_1^3}$ and $\lambda$ the constant from Lemma~\ref{lem_excmodulussize}.
		Assume that there exists no exceptional zero of level $R_0^2$ and quality $\lambda\delta_1^2$. There exists $c_1>0$ such that for $\epsilon = e^{-c \delta_1^{-1/2}}$ we have 
			\begin{align}
				\label{eq_lem_finalunex_1} \Lambda(n)\Lambda_2(n+2)&\gtrapprox_{\epsilon} c_1  r_{P_1}(n)r_{P_1}(n+2).
			\end{align}

        We fix again the choices $P_0=N^{\delta_1},D_1=N^{\delta_1^3/100}$ and start by applying Proposition~\ref{le_chensieve} which gives us the existence of main-sieves $\omega_{\textup{M}},\Omega_{\textup{M}},\Omega'_{\textup{M}}$ as in Definition~\ref{def:mainsieve} such that
        \begin{align}\label{eq:finalunex1}
            \Lambda(n)\Lambda_2(n+2) \gtrapprox_{\epsilon} g_1(n)-g_2(n)+g_3(n),
        \end{align}
        with 
        \begin{align*}
            g_1(n)&=\Lambda(n)\Omega(n+2)\omega_{\textnormal{M}}(n+2)\\
    g_2(n)&=(3/5+\delta_1)c_{E_3^*}\Omega(n)\Omega_{\textnormal{M}}(n)\Lambda_{E_3^*}(n+2)\\
    g_3(n)&=\Lambda(n)\bigl(\omega -\Omega\bigr)(n+2)\Omega'_{\textnormal{M}}(n+2).
        \end{align*}
        We define the following constants that are related to our main-sieves: 
		\begin{align*}
        \mathcal{V}(\omega_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}\\
        \mathcal{V}(\Omega_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}\\
        \mathcal{V}(\Omega'_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^{\Omega'}_{\textup{M}}(d)}{\varphi(d)}.
    \end{align*}
    Here each $\mathcal{V}(\cdot)$ carries the same normalising product $\prod_{P_1\le p<N^{1/10}}(1-1/p)^{-1}$ emitted by Proposition~\ref{prop_MSremoval}, even though $\Omega_{\textup{M}}$ is constructed on the larger range $[P_1,N^{1/6})$ --- this deliberate normalisation is the source of the constant $3/5$ in $g_2$.
       The next task is to remove the main-sieve. Proposition~\ref{prop_MSremoval} together with the fact that $\epsilon=e^{-c \delta_1^{-1/2}}\geq N^{-(\delta_1/10)^4}$ gives us
        \begin{align*}
            g_1(n)&\approx_\epsilon  \mathcal{V}(\omega_{\textup{M}}) \Lambda(n)\Omega(n+2) \\
            g_2(n)&\approx_\epsilon \mathcal{V}(\Omega_{\textup{M}})(3/5+\delta_1)c_{E_3^*}\Omega(n)\Lambda_{E_3^*}(n+2)\\
            g_3(n)&\approx_\epsilon \mathcal{V}(\Omega'_{\textup{M}}) \Lambda(n)\bigl(\omega -\Omega\bigr)(n+2).
        \end{align*}

    We consider the contribution of each $g_i$ separately now. We start with $g_3$ and show that it is negligible. Indeed, using the facts that $\Omega\geq \omega $, that $\mathcal{V}(\Omega'_{\textup{M}})$ is bounded by~\eqref{eq:chentrivial_numerics}, and applying Corollary~\ref{cor_upperlowersieve}, we get
    \begin{align*}
        0&\geq \mathcal{V}(\Omega'_{\textup{M}}) \Lambda(n)\bigl(\omega -\Omega\bigr)(n+2)  \\
        & \gg \mathcal{V}(\Omega'_{\textup{M}}) \delta_1^{-4} \Omega(n)\bigl(\omega -\Omega\bigr)(n+2)\\
        &\approx_{\epsilon}0,
    \end{align*}
    as long as $\epsilon\gg \delta_1^{-4} e^{-\delta_1^{-1}/10} $, which is acceptable. Thus,
    \begin{align}\label{eq_finalproof_2}
        g_3(n)\approx_{\epsilon}0.
    \end{align}


 For $g_1$, an application of Proposition~\ref{prop_reducetorough} shows
    \begin{align*}
        g_1(n)\approx_\epsilon  \mathcal{V}(\omega_{\textup{M}}) r_{P_0}(n)\Omega(n+2).
    \end{align*}
    By definition $r_{P_0}=r_{P_1}r_{[P_1,P_0)}$ and we can use Lemma~\ref{lem:P_1P_0majo} to lower bound
    \begin{align*}
        r_{P_0}\geq r_{P_1} \omega_{[P_1,P_0)}.
    \end{align*}
    Since $\Omega$ is non-negative, we obtain
    \begin{align*}
        g_1(n)\gtrapprox_{\epsilon} \mathcal{V}(\omega_{\textup{M}}) r_{P_1} \omega_{[P_1,P_0)}(n)\Omega(n+2).
    \end{align*}
    We now remove the $[P_1,P_0)$ sieve component via Proposition~\ref{prop_MSremoval}. Together with~\eqref{eq:P1P0majo1} of Lemma~\ref{lem:P_1P_0majo} and  two applications of Corollary~\ref{cor_upperlowersieve} (recalling $\omega\leq r_{P_1}\leq \Omega$), we obtain
    \begin{align}
        \nonumber g_1(n)&\gtrapprox_{\epsilon}  \mathcal{V}(\omega_{\textup{M}}) r_{P_1} \omega_{[P_1,P_0)}(n)\Omega(n+2)\\
       \label{eq:finalunex2} &\approx_{\epsilon} \mathcal{V}(\omega_{\textup{M}}) r_{P_1}(n)r_{P_1}(n+2).
    \end{align}



For $g_2$ we similarly apply first Proposition~\ref{prop_reducetorough} to get
\begin{align*}
    g_2(n)\approx_\epsilon \mathcal{V}(\Omega_{\textup{M}})(3/5+\delta_1)c_{E_3^*}\Omega(n) r_{P_0}(n+2).
\end{align*}
We can then follow the same steps as for $g_1$, with the exception of using an upper bound sieve in the range $[P_1,P_0)$, since $g_2$ appears with negative sign. This shows
\begin{align}
      \label{eq:finalunex3}   -g_2(n)\gtrapprox_{\epsilon}  -\mathcal{V}(\Omega_{\textup{M}})(3/5+\delta_1)c_{E_3^*} r_{P_1}(n)r_{P_1}(n+2).
\end{align}


    Combining~\eqref{eq:finalunex1},~\eqref{eq_finalproof_2},~\eqref{eq:finalunex2}, and~\eqref{eq:finalunex3}, we have shown that
    \begin{align*}
        \Lambda(n)\Lambda_2(n+2) \gtrapprox_{\epsilon} \bigg(\mathcal{V}(\omega_{\textup{M}})-\mathcal{V}(\Omega_{\textup{M}})(3/5+\delta_1)c_{E_3^{*}}\bigg) r_{P_1}(n)r_{P_1}(n+2).
    \end{align*}
    By~\eqref{eq:chenlower_numerics}, the leading constant is lower bounded away from $0$ if $\delta_1$ is small enough in absolute terms.

\begin{align*}
        \mathcal{V}(\omega_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}\\
        \mathcal{V}(\Omega_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}\\
        \mathcal{V}(\Omega'_{\textup{M}})&\coloneqq\prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda^{\Omega'}_{\textup{M}}(d)}{\varphi(d)}.
    \end{align*}

Applying a simple upper bound sieve, we see that
\begin{align*}
	\Lambda(n)\Lambda_2(n+2)&\leq \delta_1^{-8}r_{P_1}(n)r_{P_1}(n+2)\\
	&\leq \delta_1^{-8}\Omega(n)\Omega(n+2).
\end{align*}
Thus, by the non-negativity of $\Lambda(n)\Lambda_2(n+2)$, the definition of $\gtrapprox_{\epsilon}$, and Lemma~\ref{lem_finalunex}, there exist a constant $c_1>0$ and a function $E_1$ fulfilling
\begin{align*}
	\Lambda \Lambda_2^+*\Lambda \Lambda_2^+(m)&\geq  c_1 \Lambda \Lambda_2^+* r_{P_1} r^+_{P_1}(m)+\Lambda \Lambda_2^+*E_1(m),
\end{align*}
and such that for all natural numbers $m\in [5N/4,7N/4]$ with at most $N^{1-(\delta_1/10)^{4}}$ exceptions we have
\begin{align*}
	|\Lambda \Lambda_2^+*E_1(m)|\ll \delta_1^{-8} e^{-c\delta_1^{-1/2}}  m \mathfrak{S}(m).
\end{align*}
Similarly, using the non-negativity of $r_{P_1}(n)r_{P_1}(n+2)$, there exists a function $E_2$ whose contribution is bounded in the same manner and such that
\begin{align*}
	c_1 \Lambda \Lambda_2^+* r_{P_1} r^+_{P_1}(m)&\geq c_1^2 r_{P_1} r^+_{P_1}* r_{P_1} r^+_{P_1}(m)+E_2* r_{P_1} r^+_{P_1}(m).
\end{align*}
  Finally, using upper and lower bound pre-sieves in conjunction with Corollary~\ref{cor_upperlowersieve} and Proposition~\ref{prop_presieveasmyp}, we get the asymptotics 
\begin{align*}
	r_{P_1} r^+_{P_1}* r_{P_1} r^+_{P_1}(m)=m \mathfrak{S}(m)+O\left(m \mathfrak{S}(m) e^{-\delta_1^{-1}/10}\right).
\end{align*}
If $\delta_1$ is sufficiently small in absolute terms, the factors $e^{-\delta_1^{-1}/10}$ and $\delta_1^{-8} e^{-c\delta_1^{-1/2}}$ are small. We conclude from our chain of inequalities and error term estimates that
\begin{align*}
	\Lambda \Lambda_2^+*\Lambda \Lambda_2^+(m)\geq \frac{c_1^2}{2} m \mathfrak{S}(m)
\end{align*}
for all natural numbers $m\in [5N/4,7N/4]$ with $\ll N^{1-(\delta_1/10)^{4}}$ exceptions. Since $\mathfrak{S}(m)\gg 1$ for all $m\equiv 4\pmod{6}$, this proves Theorem~\ref{MT1} in the unexceptional case, after sorting $m$ into intervals of the form $[5N/4,7N/4]$.

\label{lem_finalex}
             Let $P_1=N^{\delta_1^4},R_0=N^{\delta_1^3}$ and $\lambda$ the constant from Lemma~\ref{lem_excmodulussize}.
				Assume that there exists an exceptional character $\widetilde{\chi}$ with exceptional zero $\widetilde{\beta}$ of level $R_0^2$ and quality $\lambda\delta_1^2$. There exist $c_1>0$ such that the following holds. Let 
				\begin{align*}
