    \approx_{\widetilde{\epsilon}}& \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1} \mathcal{V}(\Omega'_{\textup{M}}) (1-n^{\widetilde{\beta}-1})r_{P_0}(n)\bigl(\omega -\Omega\bigr)(n+2)\\
