    \mathbf{1}_{\widetilde{\chi}(n)=-1}g_1(n)&\gtrapprox_{\epsilon} \mathcal{V}(\omega_{\textup{M}}) (1+n^{\widetilde{\beta}-1})r_{P_1}(n)r_{P_1}(n+2)
