and
\begin{align*}
    -\mathbf{1}_{\widetilde{\chi}(n)=-1}g_2(n)&\gtrapprox_\epsilon  -\mathcal{V}(\Omega_{\textup{M}})(3/5+\delta_1)c_{E_3^*} (1-\widetilde{\chi}(n+2)n^{\widetilde{\beta}-1})r_{P_1}(n)r_{P_1}(n+2)\\
