				We use~\eqref{eq_lem_finalex_1} of Lemma~\ref{lem_finalex} and follow the same strategy as in the unexceptional case to get
				\begin{align*}
					\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+(m)\geq c_1^2 \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}*\mathbf{1}_{\widetilde{\chi}(\cdot)=-1} r_{P_1} r^+_{P_1}(m)+\widetilde{E}(m),
				\end{align*}
				where
				\begin{align*}
					|\widetilde{E}(m)|\ll \delta_1^{-8} e^{-c \delta_1^{-1/2}} m \mathfrak{S}(m).
				\end{align*}
				for all natural numbers $m\in [5N/4,7N/4]$ with at most $O(N^{1-(\delta_1/10)^4})$ exceptions. By the first case of Proposition~\ref{prop_fundlem_exceptional} and the lower bound of the exceptional modulus~\eqref{eq:rlowerbound} we get
				\begin{align*}
					\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}*\mathbf{1}_{\widetilde{\chi}(\cdot)=-1} r_{P_1} r^+_{P_1}(m)=m \mathfrak{S}(m)\left(\frac{1+\sigma_1(m)}{4}+O(\delta_1^{-5}(\log N)^{-1})\right)\bigl(1+ O(e^{-c \delta_1^{-1}})\bigr).
				\end{align*}
                    This shows that
				\begin{align*}
					\Lambda \Lambda_2^+*\Lambda \Lambda_2^+(m)\geq \frac{1}{10} m \mathfrak{S}(m)
				\end{align*}
				for all natural numbers $m\in [5N/4,7N/4]$ with 
				\begin{align*}
					\sigma_1(m)\geq -1/2,
				\end{align*}
				apart from
				$O(N^{1-(\delta_1/10)^4})$ exceptions.  It remains to prove Theorem~\ref{MT1} under the assumption that
				\begin{align}\label{eq_MT1exceptional_assumptions}
					\sigma_1(m)< -1/2.
				\end{align}

				Multiplying now one of the functions with $\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}$, we have
				\begin{align*}
					\Lambda \Lambda_2^+*\Lambda \Lambda_2^+(m)&\geq \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}\Lambda \Lambda_2^+(m).
				\end{align*}
				By~\eqref{eq_lem_finalex_2} there exists an arithmetic function $\widetilde{E}_1$ with
				\begin{align*}
					&\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}\Lambda \Lambda_2^+(m)\\
					\geq& c_1 (1-\widetilde{\beta})(\log N)\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1}r_{P_1}^+(m)+O(\Lambda \Lambda_2^+*\widetilde{E}_1(m))
				\end{align*}
				such that
				\begin{align*}
					|\Lambda \Lambda_2^+*\widetilde{E}_1(m)|\ll \delta_1^{-8} (1-\widetilde{\beta})(\log N) e^{-c \delta_1^{-1/2}} m\mathfrak{S}(m)
				\end{align*}
				for all natural numbers $m\in [5N/4,7N/4]$ with at most $O(N^{1-(\delta_1/10)^4})$ exceptions. 
				Using the non-negativity of $r_{P_1}(n)r_{P_1}(n+2)$ and~\eqref{eq_lem_finalex_1}, there exists an arithmetic function $\widetilde{E}_2$ such that
				\begin{align*}
					&c_1 (1-\widetilde{\beta})(\log N)\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1}r_{P_1}^+(m)\\
					\geq& c_1^2 (1-\widetilde{\beta})(\log N) \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}* \mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1} r^+_{P_1}(m)\\
					&+(1-\widetilde{\beta})(\log N)\widetilde{E}_2* r_{P_1} r^+_{P_1}(m)
				\end{align*}
				 with
				\begin{align*}
					|(1-\widetilde{\beta})(\log N)\widetilde{E}_2* r_{P_1} r^+_{P_1}(m)|\ll (1-\widetilde{\beta})(\log N) e^{-c \delta_1^{-1/2}} m\mathfrak{S}(m),
				\end{align*}
				outside of an acceptable exceptional set of natural numbers $m$. By the second case of Proposition~\ref{prop_fundlem_exceptional},
				\begin{align*}
					&c_1^2 (1-\widetilde{\beta})(\log N) \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}* \mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1} r^+_{P_1}(m)\\
					=&c_1^2 (1-\widetilde{\beta})(\log N)m\mathfrak{S}(m)\Bigl( \frac{1-\sigma_1(m)-\sigma_2(m)}{8}+O(\delta_1^{-3}(\log N)^{-1/3})\Bigr)\bigl(1+ O(e^{-c \delta_1^{-1}})\bigr).
				\end{align*}
				Since we can assume~\eqref{eq_MT1exceptional_assumptions} and since  $|\sigma_2(m)|\leq 1$, we have
				\begin{align*}
					\frac{1-\sigma_1(m)-\sigma_2(m)}{8}+O(\delta_1^{-3}(\log N)^{-1/3})\geq 1/16+O(\delta_1^{-3}(\log N)^{-1/3}).
				\end{align*}
				If $\delta_1$ is sufficiently small in absolute terms, together with~\eqref{eq:exczerolowerbound} and the fact that $\mathfrak{S}(m)\gg 1$ for $m\equiv 4 \pmod 6$, this shows that
				\begin{align*}
					\Lambda \Lambda_2^+*\Lambda \Lambda_2^+(m)\geq \frac{1}{20} (1-\widetilde{\beta})(\log N)m \mathfrak{S}(m)\gg N^{1-\delta_1^6}
				\end{align*}
				for all natural numbers $m\in [5N/4,7N/4], m\equiv 4\pmod 6$ that fulfil~\eqref{eq_MT1exceptional_assumptions}, apart from $O(N^{1-(\delta_1/10)^4})$ exceptions.

\begin{align*}
					&c_1 (1-\widetilde{\beta})(\log N)\mathbf{1}_{\widetilde{\chi}(\cdot)=-1}\Lambda \Lambda_2^+*\mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1}r_{P_1}^+(m)\\
					\geq& c_1^2 (1-\widetilde{\beta})(\log N) \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}* \mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1} r^+_{P_1}(m)\\
					&+(1-\widetilde{\beta})(\log N)\widetilde{E}_2* r_{P_1} r^+_{P_1}(m)
				\end{align*}

\begin{align*}
					|(1-\widetilde{\beta})(\log N)\widetilde{E}_2* r_{P_1} r^+_{P_1}(m)|\ll (1-\widetilde{\beta})(\log N) e^{-c \delta_1^{-1/2}} m\mathfrak{S}(m),
				\end{align*}

\begin{align*}
					&c_1^2 (1-\widetilde{\beta})(\log N) \mathbf{1}_{\widetilde{\chi}(\cdot)=-1}r_{P_1} r^+_{P_1}* \mathbf{1}_{\widetilde{\chi}(\cdot)=\widetilde{\chi}(\cdot+2)=1}r_{P_1} r^+_{P_1}(m)\\
					=&c_1^2 (1-\widetilde{\beta})(\log N)m\mathfrak{S}(m)\Bigl( \frac{1-\sigma_1(m)-\sigma_2(m)}{8}+O(\delta_1^{-3}(\log N)^{-1/3})\Bigr)\bigl(1+ O(e^{-c \delta_1^{-1}})\bigr).
